"""Optional developer analysis: ffmpeg; preserves all original MP3 bytes. Run from any directory."""
from pathlib import Path
from array import array
import subprocess,json,math,hashlib
root=Path(__file__).resolve().parents[1];base=root/'assets/sounds/classic-v2'
manifest=json.loads((base/'manifest.json').read_text());target=-26.0;rows=[]
for s in manifest['sounds']:
 path=base/(s['id']+'.mp3')
 raw=subprocess.run(['ffmpeg','-v','error','-i',str(path),'-f','f32le','-acodec','pcm_f32le','-ac','2','-ar','44100','-'],capture_output=True,check=True).stdout
 samples=array('f');samples.frombytes(raw);window=4410
 power=[sum(v*v for v in samples[i:i+window])/len(samples[i:i+window]) for i in range(0,len(samples),window) if len(samples[i:i+window])>=440]
 # 50ms active windows, gated within 10dB of the strongest window, exclude long quiet tails.
 strongest=max(power);active=[p for p in power if p>=strongest*.1]
 db=10*math.log10(sum(active)/len(active))+20*math.log10(s['volume'])
 gain=round(min(2.75,max(.7,10**((target-db)/20))),4)
 rows.append({'id':s['id'],'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'activeDb':round(db,4),'peakDb':round(20*math.log10(max(abs(v) for v in samples)*s['volume']),4),'gain':gain,'balancedActiveDb':round(db+20*math.log10(gain),4)})
report={'version':1,'method':'stereo RMS, 50ms windows, gate -10dB from strongest window, includes original manifest gain','targetDb':target,'minGain':.7,'maxGain':2.75,'outputGain':1.5,'sounds':rows}
(base/'balance-v25.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
levels={s['id']:s['gain'] for s in rows}
(root/'src/audio/loudness.js').write_text('// Generated by scripts/balance-sounds.py; original MP3 files are unchanged.\nexport const SOUND_OUTPUT_GAIN=1.5;\nexport const SOUND_LEVEL_GAINS=Object.freeze('+json.dumps(levels,separators=(',',':'))+');\nexport const soundLevelGain=id=>SOUND_LEVEL_GAINS[id]??1;\n')
print(json.dumps({'sounds':len(rows),'beforeActiveDbRange':[min(s['activeDb'] for s in rows),max(s['activeDb'] for s in rows)],'afterActiveDbRange':[min(s['balancedActiveDb'] for s in rows),max(s['balancedActiveDb'] for s in rows)],'gainRange':[min(s['gain'] for s in rows),max(s['gain'] for s in rows)],'outputGain':1.5}))
